/**
 * Chat engine. GENERATED by tools/sync-chat.mjs from web/pages/chatbot.xhtml (the page <script>) — do not edit; change the script and run `npm run chat:sync`.
 *
 * The page script of the Java chat screen, same behaviour line by line.
 *
 * WHY it is imperative DOM code and not Angular components: the Java page is a data-driven DOM application
 * (inbox, messages, 5 modals, an analytics dashboard … all drawn from API data as HTML strings with inline handlers,
 * socket events patching the lists, timers). Porting it 1:1 is what guarantees the screen, texts and states are
 * identical to the production system; the template (chat.html) and stylesheet (chat.scss) are the Java markup / CSS
 * verbatim and the engine binds to them through the same ids / data-* contract as before.
 * "@ts-nocheck": the source is ES5 written for a browser global scope; typing it would change it, not port it.
 *
 * What changed versus the Java file (all of it lives in tools/sync-chat.mjs):
 *   - the environment is injected (ChatEnv): API base, fetch (mock backend in dev), Socket.IO factory, feature flags,
 *     language, employee / branch ids, i18n, dialogs, asset URLs — in Java these were EL expressions, template
 *     scripts (swal, crmShowError, the io CDN script) and relative URLs;
 *   - global listeners, timers, the socket and the window.cb* handler entry points are removed by the function returned
 *     from startChat();
 *   - links to other pages are SPA routes (/crm/prospects, /crm/opportunities/:id) instead of *.face pages;
 *   - the unused sample data of the old prototype (FB / MOCK) is dropped.
 * Every string that comes from the API or the user is still passed through esc() before it reaches innerHTML.
 */

export interface ChatEnv {
  /** the `.cb` root rendered by ChatView — the script uses document-wide ids exactly as the Java page did */
  root: HTMLElement;
  /** BFF context path, e.g. "/triplesale" (Java: first segment of location.pathname) */
  ctx: string;
  /** UI language 'th' | 'en' (Java: commonBean.currentLang) */
  lang: string;
  /** signed-in employee id (Java: commonBean.ssEmployeeId) */
  employeeId: string | number | null;
  /** active branch id (Java: commonBean.activeBranchId) */
  branchId: string | number | null;
  /** commonBean.hasFeature(...) */
  can: (feature: string) => boolean;
  /** commonBean.msg[...] */
  t: (key: string) => string;
  /** window.fetch in live mode, the mock backend in dev */
  fetch: (input: string, init?: RequestInit) => Promise<Response>;
  /** Socket.IO client factory (undefined = no realtime, like a failed CDN load) */
  io?: (url: string, opts: any) => any;
  /** URL for a file the page uploaded (dev mock keeps them in memory); '' = use <ctx>/chat-api/files/<name> */
  fileUrl?: (filename: string) => string;
  /** base URL of the static assets, ends with "/" */
  assetBase: string;
  /** swal({icon:'warning', buttons:[cancel, ok], dangerMode}) */
  confirm: (o: { title: string; text: string; cancel: string; ok: string; danger: boolean }) => Promise<boolean>;
  /** crmShowError(title, detail) */
  showError: (title: string, detail?: string) => void;
}

